package in.madhava.companion;
import android.app.*;import android.os.*;import android.Manifest;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.net.Uri;import android.webkit.*;import android.view.*;import android.widget.*;import android.security.keystore.*;import android.util.Base64;import java.io.*;import java.util.*;import java.security.*;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;

public class MainActivity extends Activity {
 private WebView web; private PermissionRequest pending; private static final String ORIGIN="https://appassets.androidplatform.net"; private SharedPreferences prefs;
 @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("vault",MODE_PRIVATE);getWindow().setStatusBarColor(Color.rgb(18,75,65));getWindow().setNavigationBarColor(Color.rgb(247,247,241));getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);
  FrameLayout root=new FrameLayout(this);root.setBackgroundColor(Color.rgb(18,75,65));web=new WebView(this);root.addView(web,new FrameLayout.LayoutParams(-1,-1));setContentView(root);
  if(Build.VERSION.SDK_INT>=30){getWindow().setDecorFitsSystemWindows(false);root.setOnApplyWindowInsetsListener((v,i)->{android.graphics.Insets bars=i.getInsets(WindowInsets.Type.systemBars());android.graphics.Insets keyboard=i.getInsets(WindowInsets.Type.ime());v.setPadding(bars.left,bars.top,bars.right,Math.max(bars.bottom,keyboard.bottom));return i;});getWindow().getInsetsController().setSystemBarsAppearance(WindowInsetsController.APPEARANCE_LIGHT_NAVIGATION_BARS,WindowInsetsController.APPEARANCE_LIGHT_STATUS_BARS|WindowInsetsController.APPEARANCE_LIGHT_NAVIGATION_BARS);}
  WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setMediaPlaybackRequiresUserGesture(false);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setSupportZoom(false);web.setBackgroundColor(Color.rgb(246,244,238));web.addJavascriptInterface(new Bridge(),"Android");web.setWebViewClient(new WebViewClient(){
   @Override public WebResourceResponse shouldInterceptRequest(WebView w,WebResourceRequest r){Uri u=r.getUrl();if(!"appassets.androidplatform.net".equals(u.getHost()))return null;try{String path=u.getPath();if(path==null||path.equals("/"))path="/index.html";path=path.substring(1);if(path.contains(".."))return missing();String mime=path.endsWith(".js")?"application/javascript":path.endsWith(".css")?"text/css":path.endsWith(".html")?"text/html":path.endsWith(".glb")?"model/gltf-binary":path.endsWith(".jpg")?"image/jpeg":path.endsWith(".png")?"image/png":"application/octet-stream";WebResourceResponse out=new WebResourceResponse(mime,"UTF-8",getAssets().open(path));Map<String,String> h=new HashMap<>();h.put("Access-Control-Allow-Origin",ORIGIN);h.put("Cache-Control","no-cache");out.setResponseHeaders(h);return out;}catch(Exception e){return missing();}}
   @Override public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){Uri u=r.getUrl();if(ORIGIN.equals(u.getScheme()+"://"+u.getHost()))return false;if("https".equals(u.getScheme()))try{startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception e){}return true;}
  });
  web.setWebChromeClient(new WebChromeClient(){
   @Override public void onPermissionRequest(PermissionRequest request){runOnUiThread(()->{if(!"https".equals(request.getOrigin().getScheme())||!"appassets.androidplatform.net".equals(request.getOrigin().getHost())){request.deny();return;}if(pending!=null){pending.deny();pending=null;}pending=request;ArrayList<String> needed=new ArrayList<>();for(String r:request.getResources()){String p=mapPermission(r);if(p!=null&&checkSelfPermission(p)!=PackageManager.PERMISSION_GRANTED)needed.add(p);}if(needed.isEmpty())grantPending();else requestPermissions(needed.toArray(new String[0]),40);});}
   @Override public void onPermissionRequestCanceled(PermissionRequest r){if(pending==r)pending=null;}
   @Override public boolean onCreateWindow(WebView v,boolean d,boolean g,Message result){return false;}
  });if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,()->web.evaluateJavascript("window.appBack&&window.appBack()",null));web.loadUrl(ORIGIN+"/index.html");
 }
 private WebResourceResponse missing(){return new WebResourceResponse("text/plain","UTF-8",404,"Not found",new HashMap<>(),new ByteArrayInputStream(new byte[0]));}
 private String mapPermission(String r){if(PermissionRequest.RESOURCE_AUDIO_CAPTURE.equals(r))return Manifest.permission.RECORD_AUDIO;if(PermissionRequest.RESOURCE_VIDEO_CAPTURE.equals(r))return Manifest.permission.CAMERA;return null;}
 private void grantPending(){PermissionRequest r=pending;pending=null;if(r==null)return;ArrayList<String> granted=new ArrayList<>();for(String resource:r.getResources()){String p=mapPermission(resource);if(p!=null&&checkSelfPermission(p)==PackageManager.PERMISSION_GRANTED)granted.add(resource);}if(granted.isEmpty())r.deny();else r.grant(granted.toArray(new String[0]));}
 @Override public void onRequestPermissionsResult(int code,String[] p,int[] results){super.onRequestPermissionsResult(code,p,results);if(code==40)grantPending();}
 @Override public void onBackPressed(){web.evaluateJavascript("window.appBack&&window.appBack()",null);}
 @Override protected void onStop(){super.onStop();if(web!=null)web.evaluateJavascript("window.appBackground&&window.appBackground()",null);getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);}
 @Override protected void onDestroy(){if(pending!=null)pending.deny();if(web!=null){web.removeJavascriptInterface("Android");web.destroy();web=null;}super.onDestroy();}
 private SecretKey vaultKey() throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(ks.containsAlias("madhava-api"))return (SecretKey)ks.getKey("madhava-api",null);KeyGenerator g=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder("madhava-api",KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());return g.generateKey();}
 final class Bridge{
  @JavascriptInterface public synchronized boolean saveKey(String value){try{Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,vaultKey());String data=Base64.encodeToString(c.doFinal(value.getBytes("UTF-8")),Base64.NO_WRAP);return prefs.edit().putString("iv",Base64.encodeToString(c.getIV(),Base64.NO_WRAP)).putString("data",data).commit();}catch(Exception e){return false;}}
  @JavascriptInterface public synchronized String getKey(){try{String data=prefs.getString("data","");if(data.isEmpty())return "";Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,vaultKey(),new GCMParameterSpec(128,Base64.decode(prefs.getString("iv",""),Base64.NO_WRAP)));return new String(c.doFinal(Base64.decode(data,Base64.NO_WRAP)),"UTF-8");}catch(Exception e){return "";}}
  @JavascriptInterface public synchronized void clearKey(){prefs.edit().clear().commit();}
  @JavascriptInterface public void setCallActive(boolean active){runOnUiThread(()->{if(active)getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);else getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);});}
  @JavascriptInterface public void finishApp(){runOnUiThread(()->finish());}
 }
}
